CREATE TEMP TABLE curriculum_revised (payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO curriculum_revised(payload) VALUES ($guide_payload$[{"slug":"talora-instructional-design-2026","task_number":1,"title":"Learner Needs Analysis","old_instructions":"[[AZ]]\n## Məqsəd\nNümunə öyrənən qrupu seç ;  Bilgi boşluqlarını müəyyən et ;  İki öyrənmə maneəsini təsvir et.\n\n## Addım-addım icra\n1. Nümunə öyrənən qrupu seç.\n2. Bilgi boşluqlarını müəyyən et.\n3. İki öyrənmə maneəsini təsvir et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nLearner needs brief. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose a learner persona ;  Identify knowledge gaps ;  Describe two learning barriers.\n\n## Step-by-step\n1. Choose a learner persona.\n2. Identify knowledge gaps.\n3. Describe two learning barriers.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nLearner needs brief. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nNümunə öyrənən qrupu seç ;  Bilgi boşluqlarını müəyyən et ;  İki öyrənmə maneəsini təsvir et.\n\n[[EN]]\nChoose a learner persona ;  Identify knowledge gaps ;  Describe two learning barriers.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Learner Needs Analysis\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Hər dərsin sonunda öyrənən nə edə bildiyini göstərməlidir.\n**Nümunə situasiya:** Talora-da ilk dəfə müraciət edən tələbənin bilmədiyi 3 addımı araşdır.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n- **Google Forms** — https://forms.google.com. Blank form aç, sualları əlavə et, yalnız uydurma cavablarla sına.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Instructional Design / Task-1. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Nümunə öyrənən qrupu seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Bilgi boşluqlarını müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. İki öyrənmə maneəsini təsvir et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Talora-da ilk dəfə müraciət edən tələbənin bilmədiyi 3 addımı araşdır. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Learner needs brief. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nTalora-da ilk dəfə müraciət edən tələbənin bilmədiyi 3 addımı araşdır.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Learner needs brief.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Öyrənmə nəticəsi, məşq və qiymətləndirmə bir-birinə uyğun olsun.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Learner Needs Analysis\nThis practical assignment is designed for beginners. Each lesson should lead to an observable learner skill.\n**Example scenario:** Identify three knowledge gaps for a student applying for the first time.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n- **Google Forms** — https://forms.google.com. Build a blank form, add questions and test with fictional responses.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Instructional Design / Task-1. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Choose a learner persona. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Identify knowledge gaps. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Describe two learning barriers. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Identify three knowledge gaps for a student applying for the first time. Document what worked and any limitations.\n7. Complete the main artifact: Learner needs brief. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nIdentify three knowledge gaps for a student applying for the first time.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Learner needs brief.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Align learning outcomes, activities and assessment.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nLearner Needs Analysis: Nümunə öyrənən qrupu seç. Bilgi boşluqlarını müəyyən et. İki öyrənmə maneəsini təsvir et. Pulsuz alətlər: Google Docs, Google Forms. Nəticə: Learner needs brief.\n\n[[EN]]\nLearner Needs Analysis: Choose a learner persona. Identify knowledge gaps. Describe two learning barriers. Free tools: Google Docs, Google Forms. Output: Learner needs brief."},{"slug":"talora-instructional-design-2026","task_number":2,"title":"Measurable Learning Outcomes","old_instructions":"[[AZ]]\n## Məqsəd\nDörd nəticə yaz ;  Bloom felindən istifadə et ;  Hər nəticə üçün ölçmə üsulu seç.\n\n## Addım-addım icra\n1. Dörd nəticə yaz.\n2. Bloom felindən istifadə et.\n3. Hər nəticə üçün ölçmə üsulu seç.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nLearning outcomes map. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nWrite four learning outcomes ;  Use observable Bloom verbs ;  Assign a measurement method.\n\n## Step-by-step\n1. Write four learning outcomes.\n2. Use observable Bloom verbs.\n3. Assign a measurement method.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nLearning outcomes map. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nDörd nəticə yaz ;  Bloom felindən istifadə et ;  Hər nəticə üçün ölçmə üsulu seç.\n\n[[EN]]\nWrite four learning outcomes ;  Use observable Bloom verbs ;  Assign a measurement method.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Measurable Learning Outcomes\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Hər dərsin sonunda öyrənən nə edə bildiyini göstərməlidir.\n**Nümunə situasiya:** 'Müraciətin 4 addımını sıralayır' kimi ölçülən öyrənmə nəticələri yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Instructional Design / Task-2. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Dörd nəticə yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Bloom felindən istifadə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Hər nəticə üçün ölçmə üsulu seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 'Müraciətin 4 addımını sıralayır' kimi ölçülən öyrənmə nəticələri yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Learning outcomes map. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n'Müraciətin 4 addımını sıralayır' kimi ölçülən öyrənmə nəticələri yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Learning outcomes map.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Öyrənmə nəticəsi, məşq və qiymətləndirmə bir-birinə uyğun olsun.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Measurable Learning Outcomes\nThis practical assignment is designed for beginners. Each lesson should lead to an observable learner skill.\n**Example scenario:** Write measurable outcomes such as listing four application steps.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Instructional Design / Task-2. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Write four learning outcomes. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Use observable Bloom verbs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Assign a measurement method. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Write measurable outcomes such as listing four application steps. Document what worked and any limitations.\n7. Complete the main artifact: Learning outcomes map. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nWrite measurable outcomes such as listing four application steps.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Learning outcomes map.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Align learning outcomes, activities and assessment.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nMeasurable Learning Outcomes: Dörd nəticə yaz. Bloom felindən istifadə et. Hər nəticə üçün ölçmə üsulu seç. Pulsuz alətlər: Google Docs. Nəticə: Learning outcomes map.\n\n[[EN]]\nMeasurable Learning Outcomes: Write four learning outcomes. Use observable Bloom verbs. Assign a measurement method. Free tools: Google Docs. Output: Learning outcomes map."},{"slug":"talora-instructional-design-2026","task_number":3,"title":"Micro-course Outline","old_instructions":"[[AZ]]\n## Məqsəd\nÜç modullu kurs skeleti qur ;  Vaxt bölgüsünü hesabla ;  Nəticə ilə mövzu uyğunluğunu göstər.\n\n## Addım-addım icra\n1. Üç modullu kurs skeleti qur.\n2. Vaxt bölgüsünü hesabla.\n3. Nəticə ilə mövzu uyğunluğunu göstər.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nCourse outline. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nOutline a three-module mini-course ;  Estimate time ;  Map topics to outcomes.\n\n## Step-by-step\n1. Outline a three-module mini-course.\n2. Estimate time.\n3. Map topics to outcomes.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nCourse outline. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nÜç modullu kurs skeleti qur ;  Vaxt bölgüsünü hesabla ;  Nəticə ilə mövzu uyğunluğunu göstər.\n\n[[EN]]\nOutline a three-module mini-course ;  Estimate time ;  Map topics to outcomes.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Micro-course Outline\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Hər dərsin sonunda öyrənən nə edə bildiyini göstərməlidir.\n**Nümunə situasiya:** Hesab yarat, proqram seç, müraciət et adlı 3 modulun xəritəsini qur.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Instructional Design / Task-3. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Üç modullu kurs skeleti qur. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Vaxt bölgüsünü hesabla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Nəticə ilə mövzu uyğunluğunu göstər. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Hesab yarat, proqram seç, müraciət et adlı 3 modulun xəritəsini qur. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Course outline. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nHesab yarat, proqram seç, müraciət et adlı 3 modulun xəritəsini qur.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Course outline.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Öyrənmə nəticəsi, məşq və qiymətləndirmə bir-birinə uyğun olsun.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Micro-course Outline\nThis practical assignment is designed for beginners. Each lesson should lead to an observable learner skill.\n**Example scenario:** Map account setup, program selection and application into three modules.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Instructional Design / Task-3. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Outline a three-module mini-course. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Estimate time. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Map topics to outcomes. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Map account setup, program selection and application into three modules. Document what worked and any limitations.\n7. Complete the main artifact: Course outline. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nMap account setup, program selection and application into three modules.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Course outline.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Align learning outcomes, activities and assessment.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nMicro-course Outline: Üç modullu kurs skeleti qur. Vaxt bölgüsünü hesabla. Nəticə ilə mövzu uyğunluğunu göstər. Pulsuz alətlər: Google Sheets. Nəticə: Course outline.\n\n[[EN]]\nMicro-course Outline: Outline a three-module mini-course. Estimate time. Map topics to outcomes. Free tools: Google Sheets. Output: Course outline."},{"slug":"talora-instructional-design-2026","task_number":4,"title":"Lesson Prototype","old_instructions":"[[AZ]]\n## Məqsəd\nBir 10 dəqiqəlik dərs yaz ;  Nümunə və təcrübə daxil et ;  Yüklənmə/oxunaqlıq kriteriyasını yoxla.\n\n## Addım-addım icra\n1. Bir 10 dəqiqəlik dərs yaz.\n2. Nümunə və təcrübə daxil et.\n3. Yüklənmə/oxunaqlıq kriteriyasını yoxla.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nLesson prototype. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCreate a ten-minute lesson ;  Add example and practice ;  Check readability and cognitive load.\n\n## Step-by-step\n1. Create a ten-minute lesson.\n2. Add example and practice.\n3. Check readability and cognitive load.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nLesson prototype. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBir 10 dəqiqəlik dərs yaz ;  Nümunə və təcrübə daxil et ;  Yüklənmə/oxunaqlıq kriteriyasını yoxla.\n\n[[EN]]\nCreate a ten-minute lesson ;  Add example and practice ;  Check readability and cognitive load.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Lesson Prototype\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Hər dərsin sonunda öyrənən nə edə bildiyini göstərməlidir.\n**Nümunə situasiya:** 10 dəqiqəlik dərsi 2 dəq giriş + 5 dəq demo + 3 dəq məşq olaraq planla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n- **Google Slides** — https://slides.google.com. Bir slaydda bir əsas fikir yerləşdir, sonunda PDF eksport et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Instructional Design / Task-4. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Bir 10 dəqiqəlik dərs yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Nümunə və təcrübə daxil et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Yüklənmə/oxunaqlıq kriteriyasını yoxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 10 dəqiqəlik dərsi 2 dəq giriş + 5 dəq demo + 3 dəq məşq olaraq planla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Lesson prototype. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n10 dəqiqəlik dərsi 2 dəq giriş + 5 dəq demo + 3 dəq məşq olaraq planla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Lesson prototype.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Öyrənmə nəticəsi, məşq və qiymətləndirmə bir-birinə uyğun olsun.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Lesson Prototype\nThis practical assignment is designed for beginners. Each lesson should lead to an observable learner skill.\n**Example scenario:** Plan a ten-minute lesson with introduction, demo and practice.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n- **Google Slides** — https://slides.google.com. Use one idea per slide, then export the presentation as PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Instructional Design / Task-4. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Create a ten-minute lesson. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Add example and practice. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Check readability and cognitive load. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Plan a ten-minute lesson with introduction, demo and practice. Document what worked and any limitations.\n7. Complete the main artifact: Lesson prototype. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nPlan a ten-minute lesson with introduction, demo and practice.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Lesson prototype.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Align learning outcomes, activities and assessment.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nLesson Prototype: Bir 10 dəqiqəlik dərs yaz. Nümunə və təcrübə daxil et. Yüklənmə/oxunaqlıq kriteriyasını yoxla. Pulsuz alətlər: Google Docs, Google Slides. Nəticə: Lesson prototype.\n\n[[EN]]\nLesson Prototype: Create a ten-minute lesson. Add example and practice. Check readability and cognitive load. Free tools: Google Docs, Google Slides. Output: Lesson prototype."},{"slug":"talora-instructional-design-2026","task_number":5,"title":"Assessment Rubric","old_instructions":"[[AZ]]\n## Məqsəd\nBeş sual və bir praktik tapşırıq hazırla ;  Qəbul meyarını yaz ;  Sualın ölçdüyü nəticəni göstər.\n\n## Addım-addım icra\n1. Beş sual və bir praktik tapşırıq hazırla.\n2. Qəbul meyarını yaz.\n3. Sualın ölçdüyü nəticəni göstər.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nAssessment pack. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nWrite five questions and one practical task ;  Define rubric ;  Map items to outcomes.\n\n## Step-by-step\n1. Write five questions and one practical task.\n2. Define rubric.\n3. Map items to outcomes.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nAssessment pack. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBeş sual və bir praktik tapşırıq hazırla ;  Qəbul meyarını yaz ;  Sualın ölçdüyü nəticəni göstər.\n\n[[EN]]\nWrite five questions and one practical task ;  Define rubric ;  Map items to outcomes.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Assessment Rubric\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Hər dərsin sonunda öyrənən nə edə bildiyini göstərməlidir.\n**Nümunə situasiya:** 5 test sualı və 1 praktik forma tapşırığına uyğun rubrik hazırla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Forms** — https://forms.google.com. Blank form aç, sualları əlavə et, yalnız uydurma cavablarla sına.\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Instructional Design / Task-5. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Beş sual və bir praktik tapşırıq hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Qəbul meyarını yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Sualın ölçdüyü nəticəni göstər. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 5 test sualı və 1 praktik forma tapşırığına uyğun rubrik hazırla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Assessment pack. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n5 test sualı və 1 praktik forma tapşırığına uyğun rubrik hazırla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Assessment pack.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Öyrənmə nəticəsi, məşq və qiymətləndirmə bir-birinə uyğun olsun.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Assessment Rubric\nThis practical assignment is designed for beginners. Each lesson should lead to an observable learner skill.\n**Example scenario:** Create five quiz items and a rubric for completing a sample form.\n\n## Free tools and platforms\n- **Google Forms** — https://forms.google.com. Build a blank form, add questions and test with fictional responses.\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Instructional Design / Task-5. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Write five questions and one practical task. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Define rubric. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Map items to outcomes. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Create five quiz items and a rubric for completing a sample form. Document what worked and any limitations.\n7. Complete the main artifact: Assessment pack. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCreate five quiz items and a rubric for completing a sample form.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Assessment pack.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Align learning outcomes, activities and assessment.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nAssessment Rubric: Beş sual və bir praktik tapşırıq hazırla. Qəbul meyarını yaz. Sualın ölçdüyü nəticəni göstər. Pulsuz alətlər: Google Forms, Google Sheets. Nəticə: Assessment pack.\n\n[[EN]]\nAssessment Rubric: Write five questions and one practical task. Define rubric. Map items to outcomes. Free tools: Google Forms, Google Sheets. Output: Assessment pack."},{"slug":"talora-instructional-design-2026","task_number":6,"title":"Feedback and Remediation","old_instructions":"[[AZ]]\n## Məqsəd\nSəhv cavaba faydalı feedback yaz ;  İki əlavə resurs təklif et ;  İrəliləyişə uyğun təkrar məzmun planla.\n\n## Addım-addım icra\n1. Səhv cavaba faydalı feedback yaz.\n2. İki əlavə resurs təklif et.\n3. İrəliləyişə uyğun təkrar məzmun planla.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nFeedback matrix. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nWrite actionable feedback ;  Offer two follow-up resources ;  Plan remediation for low scores.\n\n## Step-by-step\n1. Write actionable feedback.\n2. Offer two follow-up resources.\n3. Plan remediation for low scores.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nFeedback matrix. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nSəhv cavaba faydalı feedback yaz ;  İki əlavə resurs təklif et ;  İrəliləyişə uyğun təkrar məzmun planla.\n\n[[EN]]\nWrite actionable feedback ;  Offer two follow-up resources ;  Plan remediation for low scores.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Feedback and Remediation\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Hər dərsin sonunda öyrənən nə edə bildiyini göstərməlidir.\n**Nümunə situasiya:** Yanlış cavab üçün 'niyə' və 'nəyi təkrar öyrənməli' feedback-i yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Instructional Design / Task-6. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Səhv cavaba faydalı feedback yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. İki əlavə resurs təklif et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. İrəliləyişə uyğun təkrar məzmun planla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Yanlış cavab üçün 'niyə' və 'nəyi təkrar öyrənməli' feedback-i yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Feedback matrix. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nYanlış cavab üçün 'niyə' və 'nəyi təkrar öyrənməli' feedback-i yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Feedback matrix.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Öyrənmə nəticəsi, məşq və qiymətləndirmə bir-birinə uyğun olsun.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Feedback and Remediation\nThis practical assignment is designed for beginners. Each lesson should lead to an observable learner skill.\n**Example scenario:** Provide feedback explaining errors and recommended remediation.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Instructional Design / Task-6. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Write actionable feedback. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Offer two follow-up resources. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Plan remediation for low scores. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Provide feedback explaining errors and recommended remediation. Document what worked and any limitations.\n7. Complete the main artifact: Feedback matrix. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nProvide feedback explaining errors and recommended remediation.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Feedback matrix.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Align learning outcomes, activities and assessment.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nFeedback and Remediation: Səhv cavaba faydalı feedback yaz. İki əlavə resurs təklif et. İrəliləyişə uyğun təkrar məzmun planla. Pulsuz alətlər: Google Docs. Nəticə: Feedback matrix.\n\n[[EN]]\nFeedback and Remediation: Write actionable feedback. Offer two follow-up resources. Plan remediation for low scores. Free tools: Google Docs. Output: Feedback matrix."},{"slug":"talora-instructional-design-2026","task_number":7,"title":"Accessible Learning Content","old_instructions":"[[AZ]]\n## Məqsəd\nBaşlıqları və alt mətnləri yoxla ;  Rəngə bağlı işarələri əvəz et ;  Klaviatura və subtitr dəstəyini qiymətləndir.\n\n## Addım-addım icra\n1. Başlıqları və alt mətnləri yoxla.\n2. Rəngə bağlı işarələri əvəz et.\n3. Klaviatura və subtitr dəstəyini qiymətləndir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nAccessibility checklist. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCheck headings and alt text ;  Avoid color-only cues ;  Evaluate keyboard and caption support.\n\n## Step-by-step\n1. Check headings and alt text.\n2. Avoid color-only cues.\n3. Evaluate keyboard and caption support.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nAccessibility checklist. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBaşlıqları və alt mətnləri yoxla ;  Rəngə bağlı işarələri əvəz et ;  Klaviatura və subtitr dəstəyini qiymətləndir.\n\n[[EN]]\nCheck headings and alt text ;  Avoid color-only cues ;  Evaluate keyboard and caption support.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Accessible Learning Content\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Hər dərsin sonunda öyrənən nə edə bildiyini göstərməlidir.\n**Nümunə situasiya:** Dərsdə subtitr, alt text, başlıq sırası və klaviatura dəstəyini yoxla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Instructional Design / Task-7. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Başlıqları və alt mətnləri yoxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Rəngə bağlı işarələri əvəz et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Klaviatura və subtitr dəstəyini qiymətləndir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Dərsdə subtitr, alt text, başlıq sırası və klaviatura dəstəyini yoxla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Accessibility checklist. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nDərsdə subtitr, alt text, başlıq sırası və klaviatura dəstəyini yoxla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Accessibility checklist.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Öyrənmə nəticəsi, məşq və qiymətləndirmə bir-birinə uyğun olsun.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Accessible Learning Content\nThis practical assignment is designed for beginners. Each lesson should lead to an observable learner skill.\n**Example scenario:** Audit captions, alt text, heading order and keyboard accessibility.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Instructional Design / Task-7. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Check headings and alt text. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Avoid color-only cues. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Evaluate keyboard and caption support. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Audit captions, alt text, heading order and keyboard accessibility. Document what worked and any limitations.\n7. Complete the main artifact: Accessibility checklist. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nAudit captions, alt text, heading order and keyboard accessibility.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Accessibility checklist.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Align learning outcomes, activities and assessment.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nAccessible Learning Content: Başlıqları və alt mətnləri yoxla. Rəngə bağlı işarələri əvəz et. Klaviatura və subtitr dəstəyini qiymətləndir. Pulsuz alətlər: Google Docs. Nəticə: Accessibility checklist.\n\n[[EN]]\nAccessible Learning Content: Check headings and alt text. Avoid color-only cues. Evaluate keyboard and caption support. Free tools: Google Docs. Output: Accessibility checklist."},{"slug":"talora-instructional-design-2026","task_number":8,"title":"Pilot Testing","old_instructions":"[[AZ]]\n## Məqsəd\nÜç test öyrənəni simulyasiya et ;  Dərs anlaşılırlığını ölç ;  Test nəticələrini sənədləşdir.\n\n## Addım-addım icra\n1. Üç test öyrənəni simulyasiya et.\n2. Dərs anlaşılırlığını ölç.\n3. Test nəticələrini sənədləşdir.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nPilot test report. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nRun three synthetic learner walkthroughs ;  Measure clarity ;  Document pilot observations.\n\n## Step-by-step\n1. Run three synthetic learner walkthroughs.\n2. Measure clarity.\n3. Document pilot observations.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nPilot report. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nÜç test öyrənəni simulyasiya et ;  Dərs anlaşılırlığını ölç ;  Test nəticələrini sənədləşdir.\n\n[[EN]]\nRun three synthetic learner walkthroughs ;  Measure clarity ;  Document pilot observations.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Pilot Testing\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Hər dərsin sonunda öyrənən nə edə bildiyini göstərməlidir.\n**Nümunə situasiya:** Üç uydurma öyrənən profili ilə dərsi addım-addım simulyasiya et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Forms** — https://forms.google.com. Blank form aç, sualları əlavə et, yalnız uydurma cavablarla sına.\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Instructional Design / Task-8. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Üç test öyrənəni simulyasiya et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Dərs anlaşılırlığını ölç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Test nəticələrini sənədləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Üç uydurma öyrənən profili ilə dərsi addım-addım simulyasiya et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Pilot test report. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nÜç uydurma öyrənən profili ilə dərsi addım-addım simulyasiya et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Pilot test report.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Öyrənmə nəticəsi, məşq və qiymətləndirmə bir-birinə uyğun olsun.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Pilot Testing\nThis practical assignment is designed for beginners. Each lesson should lead to an observable learner skill.\n**Example scenario:** Walk through the lesson using three fictional learner personas.\n\n## Free tools and platforms\n- **Google Forms** — https://forms.google.com. Build a blank form, add questions and test with fictional responses.\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Instructional Design / Task-8. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Run three synthetic learner walkthroughs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Measure clarity. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Document pilot observations. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Walk through the lesson using three fictional learner personas. Document what worked and any limitations.\n7. Complete the main artifact: Pilot report. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nWalk through the lesson using three fictional learner personas.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Pilot report.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Align learning outcomes, activities and assessment.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nPilot Testing: Üç test öyrənəni simulyasiya et. Dərs anlaşılırlığını ölç. Test nəticələrini sənədləşdir. Pulsuz alətlər: Google Forms, Google Sheets. Nəticə: Pilot test report.\n\n[[EN]]\nPilot Testing: Run three synthetic learner walkthroughs. Measure clarity. Document pilot observations. Free tools: Google Forms, Google Sheets. Output: Pilot report."},{"slug":"talora-instructional-design-2026","task_number":9,"title":"Evaluation Plan","old_instructions":"[[AZ]]\n## Məqsəd\nƏvvəl-sonra test metrikası seç ;  Təlim nəticələrini yanlış şərh etmə ;  Ölçmə məhdudiyyətlərini yaz.\n\n## Addım-addım icra\n1. Əvvəl-sonra test metrikası seç.\n2. Təlim nəticələrini yanlış şərh etmə.\n3. Ölçmə məhdudiyyətlərini yaz.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nLearning evaluation plan. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDesign pre/post metrics ;  Avoid overstating causal effects ;  Document limitations.\n\n## Step-by-step\n1. Design pre/post metrics.\n2. Avoid overstating causal effects.\n3. Document limitations.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nEvaluation plan. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nƏvvəl-sonra test metrikası seç ;  Təlim nəticələrini yanlış şərh etmə ;  Ölçmə məhdudiyyətlərini yaz.\n\n[[EN]]\nDesign pre/post metrics ;  Avoid overstating causal effects ;  Document limitations.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Evaluation Plan\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Hər dərsin sonunda öyrənən nə edə bildiyini göstərməlidir.\n**Nümunə situasiya:** 5 suallıq əvvəl/sonra testin ölçmə cədvəlini sintetik data ilə doldur.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Instructional Design / Task-9. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Əvvəl-sonra test metrikası seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Təlim nəticələrini yanlış şərh etmə. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Ölçmə məhdudiyyətlərini yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 5 suallıq əvvəl/sonra testin ölçmə cədvəlini sintetik data ilə doldur. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Learning evaluation plan. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n5 suallıq əvvəl/sonra testin ölçmə cədvəlini sintetik data ilə doldur.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Learning evaluation plan.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Öyrənmə nəticəsi, məşq və qiymətləndirmə bir-birinə uyğun olsun.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Evaluation Plan\nThis practical assignment is designed for beginners. Each lesson should lead to an observable learner skill.\n**Example scenario:** Create a five-item pre/post learning table using synthetic scores.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Instructional Design / Task-9. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Design pre/post metrics. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Avoid overstating causal effects. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Document limitations. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Create a five-item pre/post learning table using synthetic scores. Document what worked and any limitations.\n7. Complete the main artifact: Evaluation plan. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCreate a five-item pre/post learning table using synthetic scores.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Evaluation plan.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Align learning outcomes, activities and assessment.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nEvaluation Plan: Əvvəl-sonra test metrikası seç. Təlim nəticələrini yanlış şərh etmə. Ölçmə məhdudiyyətlərini yaz. Pulsuz alətlər: Google Sheets. Nəticə: Learning evaluation plan.\n\n[[EN]]\nEvaluation Plan: Design pre/post metrics. Avoid overstating causal effects. Document limitations. Free tools: Google Sheets. Output: Evaluation plan."},{"slug":"talora-instructional-design-2026","task_number":10,"title":"Course Design Portfolio","old_instructions":"[[AZ]]\n## Məqsəd\nMəzmun və rubriki birləşdir ;  Təlimçi üçün tətbiq qeydləri yaz ;  Nəticə-demo və təkmilləşdirmələri təqdim et.\n\n## Addım-addım icra\n1. Məzmun və rubriki birləşdir.\n2. Təlimçi üçün tətbiq qeydləri yaz.\n3. Nəticə-demo və təkmilləşdirmələri təqdim et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nMicro-course portfolio. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nPackage lesson and rubrics ;  Write facilitator notes ;  Present a demonstrable learning flow.\n\n## Step-by-step\n1. Package lesson and rubrics.\n2. Write facilitator notes.\n3. Present a demonstrable learning flow.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nMicro-course portfolio. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nMəzmun və rubriki birləşdir ;  Təlimçi üçün tətbiq qeydləri yaz ;  Nəticə-demo və təkmilləşdirmələri təqdim et.\n\n[[EN]]\nPackage lesson and rubrics ;  Write facilitator notes ;  Present a demonstrable learning flow.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Course Design Portfolio\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Hər dərsin sonunda öyrənən nə edə bildiyini göstərməlidir.\n**Nümunə situasiya:** Məqsəd, kontent, quiz, rubrik və təlimçi qeydlərini bir mini-kurs kimi paketlə.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Slides** — https://slides.google.com. Bir slaydda bir əsas fikir yerləşdir, sonunda PDF eksport et.\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Instructional Design / Task-10. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Məzmun və rubriki birləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Təlimçi üçün tətbiq qeydləri yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Nəticə-demo və təkmilləşdirmələri təqdim et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Məqsəd, kontent, quiz, rubrik və təlimçi qeydlərini bir mini-kurs kimi paketlə. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Micro-course portfolio. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nMəqsəd, kontent, quiz, rubrik və təlimçi qeydlərini bir mini-kurs kimi paketlə.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Micro-course portfolio.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Öyrənmə nəticəsi, məşq və qiymətləndirmə bir-birinə uyğun olsun.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Course Design Portfolio\nThis practical assignment is designed for beginners. Each lesson should lead to an observable learner skill.\n**Example scenario:** Package goals, lesson, quiz, rubric and facilitator notes as a mini-course.\n\n## Free tools and platforms\n- **Google Slides** — https://slides.google.com. Use one idea per slide, then export the presentation as PDF.\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Instructional Design / Task-10. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Package lesson and rubrics. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Write facilitator notes. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Present a demonstrable learning flow. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Package goals, lesson, quiz, rubric and facilitator notes as a mini-course. Document what worked and any limitations.\n7. Complete the main artifact: Micro-course portfolio. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nPackage goals, lesson, quiz, rubric and facilitator notes as a mini-course.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Micro-course portfolio.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Align learning outcomes, activities and assessment.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nCourse Design Portfolio: Məzmun və rubriki birləşdir. Təlimçi üçün tətbiq qeydləri yaz. Nəticə-demo və təkmilləşdirmələri təqdim et. Pulsuz alətlər: Google Slides, Google Docs. Nəticə: Micro-course portfolio.\n\n[[EN]]\nCourse Design Portfolio: Package lesson and rubrics. Write facilitator notes. Present a demonstrable learning flow. Free tools: Google Slides, Google Docs. Output: Micro-course portfolio."}]$guide_payload$::jsonb);
DO $preflight$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id
   AND t.task_number=(e.item->>'task_number')::integer
   AND t.title=e.item->>'title'
 WHERE t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description'
 AND i.slug='talora-instructional-design-2026';
 IF (SELECT jsonb_array_length(payload) FROM curriculum_revised)<>10 OR matched<>10 THEN
  RAISE EXCEPTION 'Content version mismatch for talora-instructional-design-2026; matched %',matched;
 END IF;
END; $preflight$;
UPDATE public.internship_tasks t
SET instructions=e.item->>'new_instructions', description=e.item->>'new_description'
FROM curriculum_revised c
CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
JOIN public.internships i ON i.slug=e.item->>'slug'
WHERE i.slug='talora-instructional-design-2026'
AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
AND t.title=e.item->>'title';
DO $verify$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required AND i.slug='talora-instructional-design-2026';
 IF matched<>10 THEN RAISE EXCEPTION 'Verification failed after update for talora-instructional-design-2026: %',matched; END IF;
END; $verify$;
COMMIT;